const path = require('node:path')

// One stderr line per hook, so the order and the arguments are the recording.
const relative = (test) => path.relative(test.context.config.rootDir, test.path)
const say = (...parts) => process.stderr.write('HOOK ' + parts.join(' ') + '\n')

module.exports = class HookReporter {
  constructor(globalConfig, options, context) {
    this.rootDir = globalConfig.rootDir
    say('constructor', 'options=' + JSON.stringify(options), 'firstRun=' + context.firstRun)
  }
  onRunStart(results, options) {
    say('onRunStart', 'suites=' + results.numTotalTestSuites, 'estimatedTime=' + options.estimatedTime, 'showStatus=' + options.showStatus)
  }
  onTestFileStart(test) {
    say('onTestFileStart', relative(test))
  }
  onTestCaseStart(test, info) {
    say('onTestCaseStart', relative(test), info.fullName, 'mode=' + info.mode, 'ancestors=' + info.ancestorTitles.length)
  }
  onTestCaseResult(test, result) {
    say('onTestCaseResult', relative(test), result.fullName, result.status, 'invocations=' + result.invocations, 'retryReasons=' + (result.retryReasons || []).length)
  }
  onTestFileResult(test, result, results) {
    say('onTestFileResult', relative(test), 'failing=' + result.numFailingTests, 'skipped=' + result.skipped, 'console=' + (result.console === undefined ? 'none' : result.console.length), 'aggregateFailed=' + results.numFailedTests)
  }
  onRunComplete(contexts, results) {
    say('onRunComplete', 'contexts=' + contexts.size, 'failed=' + results.numFailedTests, 'passed=' + results.numPassedTests, 'success=' + results.success)
  }
  getLastError() {
    return new Error('deliberate reporter error')
  }
}
